from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Bts_info(EmssimCommand):
    def __init__(self, method="bts_info", timeout=60, rpc_connection_name='localRPC'):
        super(Bts_info, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Bts_info, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "bts_info"):
                self._ret['bts_info'] = data['data']

        elif ("status" in data):
            self._ret["status"] = data["status"]
